    LUIE_STRING_SKILL_SET_UNLEASHED_TERROR = "Unleashed Terror",
    LUIE_STRING_SKILL_SET_UNLEASHED_TERROR_TP = "When you deal direct damage with a Blink, Charge, Leap, Teleport, or Pull ability, you cut your enemy, causing them to bleed for |cFFFFFF<<1>>|r,  dealing |cFFFFFF<<2>>|r  over the duration and applying the Hemorrhaging status effect every tick. This ability can occur once every |cFFFFFF<<1>>|r per target and scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_VAMPIRE_LORD = "Vampire Lord",
    LUIE_STRING_SKILL_SET_VAMPIRE_LORD_TP = "Increases the bonuses and penalties of your Vampire Stage, depending on how far you've progressed.\\n\\nStage 1/2/3/4\\n\\n1%/2%/4%/6% additional Flame Damage Taken.\\n1%/2%/4%/6% increased Regular Ability cost.\\n5%/10%/15%/20% reduced Vampire Ability cost.",
    LUIE_STRING_SKILL_SET_VAMPIRES_KISS = "Vampire's Kiss",
    LUIE_STRING_SKILL_SET_VAMPIRES_KISS_TP = "When you kill an enemy, you heal for |cFFFFFF<<1>>|r Health over |cFFFFFF<<2>>|r.  This effect scales off the higher of your Max Magicka or Stamina.",
    LUIE_STRING_SKILL_SET_VANDORALLENS_RESONANCE = "Vandorallen's Resonance",
    LUIE_STRING_SKILL_SET_VANDORALLENS_RESONANCE_TP = "Dealing damage with a fully-charged Heavy Attack places an electric charge on yourself and below your enemy. After |cFFFFFF<<1>>|r, both charges explode in a 4 meter blast, each dealing |cFFFFFF<<2>>|r to enemies hit. This effect can occur once every |cFFFFFF<<3>>|r and scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_VARENS_LEGACY_TP = "When you Block, your next direct damage area of effect attack used within |cFFFFFF<<1>>|r deals an additional |cFFFFFF<<2>>|r damage. This bonus does not work with channeled effects. This effect can occur once every |cFFFFFF<<3>>|r.",
    LUIE_STRING_SKILL_SET_VASTARIES_TUTELAGE_TP = "When you resurrect an ally, you and your ally gain |cFFFFFF<<1>>|r Weapon and Spell Damage and |cFFFFFF<<2>>|r cost reduction to non-Ultimate abilities for |cFFFFFF<<3>>|r.",
    LUIE_STRING_SKILL_SET_VELOTHI_URMAGES_AMULET = "Velothi Ur-Mage's Amulet",
    LUIE_STRING_SKILL_SET_VELOTHI_URMAGES_AMULET_TP = "Increase your damage done to monsters by |cFFFFFF<<1>>|r, gain Minor Force at all times, increasing your Critical Damage done by |cFFFFFF<<2>>|r, and reduce your Light and Heavy Attack damage by |cFFFFFF<<3>>|r.",
    LUIE_STRING_SKILL_SET_VENGEANCE_LEECH = "Vengeance Leech",
    LUIE_STRING_SKILL_SET_VENGEANCE_LEECH_TP = "When you kill an enemy, you heal for |cFFFFFF<<1>>|r Health and restore |cFFFFFF<<2>>|r Magicka and Stamina.",
    LUIE_STRING_SKILL_SET_VENOMOUS_SMITE = "Venomous Smite",
    LUIE_STRING_SKILL_SET_VENOMOUS_SMITE_TP = "Dealing Critical Damage inflicts Hunter's Venom on your enemy for <<1>>, dealing <<2>> to your target and enemies within |cffffff6|r meters of them every <<3>>. This effect can occur once every <<4>> and scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_VESTMENTS_OF_THE_WARLOCK = "Vestments of the Warlock",
    LUIE_STRING_SKILL_SET_VESTMENTS_OF_THE_WARLOCK_TP = "When you cast an ability that costs resources while under |cffffff25|r% Magicka, you restore <<1>> Magicka. This effect can occur once every <<2>>.",
    LUIE_STRING_SKILL_SET_VESTURE_OF_DARLOC_BRAE = "Vesture of Darloc Brae",
    LUIE_STRING_SKILL_SET_VESTURE_OF_DARLOC_BRAE_TP = "While you are crouching and not Bracing, you restore |cFFFFFF<<1>>|r Magicka and Stamina and heal for |cFFFFFF<<2>>|r Health every second.",
    LUIE_STRING_SKILL_SET_VICIOUS_DEATH = "Vicious Death",
    LUIE_STRING_SKILL_SET_VICIOUS_DEATH_TP = "When you kill a Player, they violently explode for <<1>> to all other enemies in a |cffffff5|r meter radius. This effect scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_VIPERS_STING = "Viper's Sting",
    LUIE_STRING_SKILL_SET_VIPERS_STING_TP = "When you deal damage with a Martial melee attack, you deal an additional |cFFFFFF<<1>>|r over |cFFFFFF<<2>>|r. This effect can occur once every |cFFFFFF<<3>>|r and scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_VIRULENT_SHOT = "Virulent Shot",
    LUIE_STRING_SKILL_SET_VIRULENT_SHOT_TP = "Scatter Shot applies a damage over time effect that deals <<1>> of your initial attack as Poison Damage every <<2>> for <<3>>. The duration increases if you are farther away from your target to a maximum of |cffffff12|r seconds.",
    LUIE_STRING_SKILL_SET_VIVECS_DUALITY = "Vivec's Duality",
    LUIE_STRING_SKILL_SET_VIVECS_DUALITY_TP = "Your weapon charges over |cFFFFFF<<1>>|r while not Weapon Swapping. Once fully charged, restore |cFFFFFF<<2>>|r Magicka and Stamina after Weapon Swapping.",
    LUIE_STRING_SKILL_SET_VOIDCALLER = "Voidcaller",
    LUIE_STRING_SKILL_SET_VROLS_COMMAND = "Vrol's Command",
    LUIE_STRING_SKILL_SET_VROLS_COMMAND_TP = "After completing a fully-charged Heavy Attack, apply Major Aegis to you and up to 11  nearby group members for |cFFFFFF<<1>>|r, reducing damage taken from Dungeon, Trial, and Arena enemies by |cFFFFFF<<2>>|r. This effect can occur once every |cFFFFFF<<3>>|r.",
    LUIE_STRING_SKILL_SET_VYKANDS_SOULFURY = "Vykand's Soulfury",
    LUIE_STRING_SKILL_SET_VYKANDS_SOULFURY_TP = "While in combat, completing a fully-charged Heavy Attack grants you either |cFFFFFF<<1>>|r, |cFFFFFF<<2>>|r, or |cFFFFFF<<3>>|r for |cFFFFFF<<4>>|r, increasing your Critical Damage done by |cFFFFFF<<5>>|r%, your damage done by |cFFFFFF<<6>>|r, or your Weapon and Spell Damage by |cFFFFFF<<7>>|r.\\n\\nThis effect can occur once every |cFFFFFF<<8>>|r.",
    LUIE_STRING_SKILL_SET_VYKOSA = "Vykosa",
    LUIE_STRING_SKILL_SET_VYKOSA_TP = "When you Bash an enemy you've taunted, you frighten them with a deafening howl, applying |cFFFFFF<<1>>|r to them, lowering their Weapon and Spell Damage by |cFFFFFF<<2>>|r for |cFFFFFF<<3>>|r. This effect can occur once every |cFFFFFF<<4>>|r.",
    LUIE_STRING_SKILL_SET_WAR_MACHINE = "War Machine",
    LUIE_STRING_SKILL_SET_WAR_MACHINE_TP = "When you use an Ultimate ability while in combat, you and the closest |cffffff5|r group members within |cffffff28|r meters of you gain Major Slayer for |cffffff1|r second per |cffffff10|r Ultimate spent, increasing your damage done to Dungeon, Trial, and Arena Monsters by <<1>>.",
    LUIE_STRING_SKILL_SET_WAR_MAIDEN = "War Maiden",
    LUIE_STRING_SKILL_SET_WAR_MAIDEN_TP = "Adds |cFFFFFF<<1>>|r Weapon and Spell Damage to your Magic Damage abilities.",
    LUIE_STRING_SKILL_SET_WAY_OF_AIR = "Way of Air",
    LUIE_STRING_SKILL_SET_WAY_OF_AIR_TP = "When you use Roll Dodge, your Weapon and Spell Damage is increased by |cFFFFFF<<1>>|r for |cFFFFFF<<2>>|r.",
    LUIE_STRING_SKILL_SET_WAY_OF_FIRE = "Way of Fire",
    LUIE_STRING_SKILL_SET_WAY_OF_FIRE_TP = "When you deal damage with a Light or Heavy Attack, you deal an additional |cFFFFFF<<1>>|r. This effect can occur once every |cFFFFFF<<2>>|r and scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_WAY_OF_MARTIAL_KNOWLEDGE = "Way of Martial Knowledge",
    LUIE_STRING_SKILL_SET_WAY_OF_MARTIAL_KNOWLEDGE_TP = "While your Stamina is below |cffffff50|r%, your Light Attacks cause the enemy to take <<1>> additional damage for <<2>>. This effect can occur once every <<3>>.",
    LUIE_STRING_SKILL_SET_WHITESTRAKES_RETRIBUTION = "Whitestrake's Retribution",
    LUIE_STRING_SKILL_SET_WHITESTRAKES_RETRIBUTION_TP = "When you take damage while you are under |cffffff30|r% Health, you gain a damage shield that absorbs <<1>> damage for <<2>>. This effect can occur once every <<3>>.",
    LUIE_STRING_SKILL_SET_WHORL_OF_THE_DEPTHS = "Whorl of the Depths",
    LUIE_STRING_SKILL_SET_WHORL_OF_THE_DEPTHS_TP = "When you deal damage with a Light Attack, you apply |cFFFFFF<<1>>|r to the target, dealing |cFFFFFF<<2>>|r over |cFFFFFF<<3>>|r. When this effect ends, a 5 meter whirlpool is created under the target for |cFFFFFF<<4>>|r and deals |cFFFFFF<<5>>|r every |cFFFFFF<<6>>|r. This effect can occur once every |cFFFFFF<<7>>|r and scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_WIDOWMAKER = "Widowmaker",
    LUIE_STRING_SKILL_SET_WIDOWMAKER_TP = "When your alchemical poison fires, you drop a poisonous spore in front of you that bursts after <<1>>, dealing <<2>> over <<3>> to all enemies within |cffffff5|r meters. This effect scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_WILD_IMPULSE = "Wild Impulse",
    LUIE_STRING_SKILL_SET_WILD_IMPULSE_TP = "Reduce the cost of Impulse by |cFFFFFF<<1>>|r. Impulse places lingering elemental damage on your targets, dealing |cFFFFFF<<2>>|r Flame, |cFFFFFF<<3>>|r Shock, and |cFFFFFF<<4>>|r Frost Damage over |cFFFFFF<<5>>|r. Each element ticks once over the duration and its damage scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_WILDERQUEENS_ARCH = "Wilderqueen's Arch",
    LUIE_STRING_SKILL_SET_WILDERQUEENS_ARCH_TP = "Your Bow attacks reduce the Movement Speed of any enemy they hit by |cFFFFFF<<1>>|r and increase your Movement Speed by |cFFFFFF<<2>>|r for |cFFFFFF<<3>>|r.",
    LUIE_STRING_SKILL_SET_WINTERS_RESPITE = "Winter's Respite",
    LUIE_STRING_SKILL_SET_WINTERBORN = "Winterborn",
    LUIE_STRING_SKILL_SET_WINTERBORN_TP = "When you deal Frost Damage, you summon an ice pillar that deals <<1>> to all enemies in a |cffffff3|r meter radius. The ice pillar persists for <<2>> and reduces the Movement Speed of all enemies within the radius by <<3>>.  This effect can occur once every <<4>> and the damage scales off the higher of your Weapon or Spell Damage.",
    LUIE_STRING_SKILL_SET_WISDOM_OF_VANUS = "Wisdom of Vanus",
    LUIE_STRING_SKILL_SET_WISDOM_OF_VANUS_TP = "After completing a fully-charged Heavy Attack, you gain Major Mending for |cFFFFFF<<1>>|r,  increasing your healing done by |cFFFFFF<<2>>|r. This duration is increased with each rank of the Restoration Staff Passive of Essence Drain when using a Restoration Staff.",
    LUIE_STRING_SKILL_SET_WISE_MAGE = "Wise Mage",
    LUIE_STRING_SKILL_SET_WISE_MAGE_TP = "Enemies you damage with fully charged Heavy Attacks are afflicted with |cFFFFFF<<1>>|r for |cFFFFFF<<2>>|r, increasing their damage taken by |cFFFFFF<<3>>|r.",
    LUIE_STRING_SKILL_SET_WITCHKNIGHTS_DEFIANCE = "Witch-Knight's Defiance",
    LUIE_STRING_SKILL_SET_WITCHKNIGHTS_DEFIANCE_TP = "Increases your Weapon and Spell Damage by |cFFFFFF<<1>>|r against enemies inflicted with a Poison Damage effect.",
    LUIE_STRING_SKILL_SET_WITCHMAN_ARMOR = "Witchman Armor",
    LUIE_STRING_SKILL_SET_WITCHMAN_ARMOR_TP = "When you use an Ultimate ability, you heal for |cFFFFFF<<1>>|r Health and restore |cFFFFFF<<2>>|r Stamina and Magicka per Ultimate spent.",
    LUIE_STRING_SKILL_SET_WIZARDS_RIPOSTE = "Wizard's Riposte",
    LUIE_STRING_SKILL_SET_WIZARDS_RIPOSTE_TP = "When you take direct Critical Damage, you apply |cFFFFFF<<1>>|r to the enemy for |cFFFFFF<<2>>|r, reducing their Critical Damage done by |cFFFFFF<<3>>|r.",
    LUIE_STRING_SKILL_SET_WRATH_OF_THE_IMPERIUM = "Wrath of the Imperium",
    LUIE_STRING_SKILL_SET_WRATH_OF_THE_IMPERIUM_TP = "Adds |cFFFFFF<<1>>|r Weapon and Spell Damage to your ranged direct damage abilities.",
    LUIE_STRING_SKILL_SET_WRATHSUN = "Wrathsun",
    LUIE_STRING_SKILL_SET_WRATHSUN_TP = "When you deal damage with a |cFFFFFF<<1>>|r ability, you gain a stack of |cFFFFFF<<2>>|r for |cFFFFFF<<3>>|r, once per attack. You can have 40 stacks max and gain |cFFFFFF<<4>>|r Magicka Recovery per stack. When at max stacks, your |cFFFFFF<<1>>|r abilities deal |cFFFFFF<<5>>|r bonus damage and a Wrathful Nova is cast on the enemy, but you cannot refresh |cFFFFFF<<2>>|r.\\n\\nWhen |cFFFFFF<<2>>|r expires at max stacks, you lose |cFFFFFF<<6>>|r of your current Magicka.",
    LUIE_STRING_SKILL_SET_WRETCHED_VITALITY = "Wretched Vitality",
    LUIE_STRING_SKILL_SET_WRETCHED_VITALITY_TP = "While in combat, applying a Major Buff or Debuff with a duration to a target grants you |cFFFFFF<<1>>|r Magicka and Stamina Recovery for |cFFFFFF<<2>>|r. \\nWhile in combat, applying a Minor Buff or Debuff with a duration to a target grants you |cFFFFFF<<3>>|r Magicka and Stamina Recovery for |cFFFFFF<<4>>|r.",
    LUIE_STRING_SKILL_SET_WYRD_TREES_BLESSING = "Wyrd Tree's Blessing",
    LUIE_STRING_SKILL_SET_WYRD_TREES_BLESSING_TP = "When you cast a Magicka ability, you remove all negative effects from yourself. This effect can occur once every |cFFFFFF<<1>>|r.",
    LUIE_STRING_SKILL_SET_XANMEER_GENESIS = "Xanmeer Genesis",
    LUIE_STRING_SKILL_SET_XANMEER_GENESIS_TP = "When an enemy you have recently damaged dies, after |cFFFFFF<<1>>|r, you and allies within |cFFFFFF<<2>>|r meters of the dead enemy receive |cFFFFFF<<3>>|r Health, Magicka, and Stamina Recovery for |cFFFFFF<<4>>|r. This effect can occur once every |cFFFFFF<<5>>|r.",
    LUIE_STRING_SKILL_SET_XANMEER_SPELLWEAVER = "Xanmeer Spellweaver",
    LUIE_STRING_SKILL_SET_XANMEER_SPELLWEAVER_TP = "Increase your damage done with Flame, Frost, and Shock Damage by |cFFFFFF<<1>>|r.\\nIncrease your damage done with Burning, Chilled, and Concussion by an additional |cFFFFFF<<2>>|r.",
    LUIE_STRING_SKILL_SET_XORYNS_MASTERPIECE = "Xoryn's Masterpiece",
    LUIE_STRING_SKILL_SET_XORYNS_MASTERPIECE_TP = "Increases Max Magicka and Max Stamina by |cFFFFFF<<1>>|r for you and up to 11 other group members within 28 meters of you. This bonus persists through death.",
    LUIE_STRING_SKILL_SET_YANDIRS_MIGHT = "Yandir's Might",
    LUIE_STRING_SKILL_SET_YANDIRS_MIGHT_TP = "Dealing Critical Damage grants you a stack of <<1>>, up to one every half second. Each stack of <<1>> adds <<2>> Weapon Damage, and stacks up to |cffffff5|r times.\\n\\nCompleting a fully-charged Heavy Attack removes <<1>> and grants <<3>> for <<4>>, increasing your Weapon Damage by <<5>> per stack removed.\\n\\nYou cannot have Giant's Endurance and Might active at the same time.",
    LUIE_STRING_SKILL_SET_YSGRAMORS_BIRTHRIGHT = "Ysgramor's Birthright",
    LUIE_STRING_SKILL_SET_YSGRAMORS_BIRTHRIGHT_TP = "Adds |cFFFFFF<<1>>|r Weapon and Spell Damage to your Frost Damage abilities.",
    LUIE_STRING_SKILL_SET_ZENS_REDRESS = "Z'en's Redress",
    LUIE_STRING_SKILL_SET_ZENS_REDRESS_TP = "Your Light Attacks apply the Touch of Z'en on enemies for |cFFFFFF<<1>>|r. Enemies with the Touch of Z'en take an additional |cFFFFFF<<2>>|r more damage for each damage over time effect you've placed on them, up to |cFFFFFF<<3>>|r. Enemies can only be affected by one Touch of Z'en at a time.",
